S.lines = {
    ["%1, I don't want our last moment to be this!"] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u062A\\u0643\\u0648\\u0646 \\u0622\\u062E\\u0631 \\u0644\\u062D\\u0638\\u0629 \\u0628\\u064A\\u0646\\u0627\\u062A\\u0646\\u0627 \\u0647\\u064A\\u0643!",
    ["%1, I was somebody before all this. Please remember I was somebody."] = "\\u0643\\u0646\\u062A \\u0625\\u0646\\u0633\\u0627\\u0646\\u0629 \\u0642\\u0628\\u0644 \\u0643\\u0644 \\u0647\\u0627\\u062F. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u062A\\u0630\\u0643\\u0631 \\u0647\\u0627\\u0644\\u0634\\u064A.",
    ["%1, am I going to die? Just say it straight."] = "\\u0642\\u0648\\u0644 \\u0644\\u064A \\u0628\\u0635\\u0631\\u0627\\u062D\\u0629\\u060C \\u0631\\u062D \\u0645\\u0648\\u062A\\u061F",
    ["%1, my head's full of fog. Say something so I know where I am."] = "\\u0631\\u0627\\u0633\\u064A \\u0645\\u0644\\u064A\\u0627\\u0646 \\u0636\\u0628\\u0627\\u0628. \\u0627\\u062D\\u0643\\u064A \\u0634\\u064A \\u062D\\u062A\\u0649 \\u0623\\u0639\\u0631\\u0641 \\u0648\\u064A\\u0646 \\u0623\\u0646\\u0627.",
    ["*draws a line across their throat and points away from the horde*"] = "*\\u0628\\u062A\\u0645\\u0631\\u0631 \\u0625\\u064A\\u062F\\u0647\\u0627 \\u0639\\u0631\\u0642\\u0628\\u062A\\u0647\\u0627 \\u0648\\u0628\\u062A\\u0623\\u0634\\u0631 \\u0628\\u0639\\u064A\\u062F \\u0639\\u0646 \\u0627\\u0644\\u0645\\u0648\\u062C\\u0629*",
    ["*goes quiet* Something dead is moving nearby."] = "*\\u0628\\u062A\\u0633\\u0643\\u062A* \\u0641\\u064A \\u0634\\u064A \\u0645\\u064A\\u062A \\u0639\\u0645 \\u064A\\u062A\\u062D\\u0631\\u0643 \\u0642\\u0631\\u064A\\u0628.",
    ["*holds two fingers low, then points forward*"] = "*\\u0628\\u062A\\u0623\\u0634\\u0631 \\u0628\\u0625\\u0635\\u0628\\u0639\\u064A\\u0646 \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0644\\u0642\\u062F\\u0627\\u0645*",
    ["*holds up four fingers: small group ahead*"] = "*\\u0628\\u062A\\u0631\\u0641\\u0639 \\u0623\\u0631\\u0628\\u0639 \\u0623\\u0635\\u0627\\u0628\\u0639: \\u062C\\u0645\\u0627\\u0639\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629 \\u0642\\u062F\\u0627\\u0645*",
    ["*listens* I heard a walker."] = "*\\u0628\\u062A\\u062A\\u0633\\u0645\\u0639* \\u0633\\u0645\\u0639\\u062A \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0647\\u0645.",
    ["*makes a wide crowd signal, then urgently motions everyone back*"] = "*\\u0628\\u062A\\u0623\\u0634\\u0631 \\u0628\\u0625\\u064A\\u062F\\u0647\\u0627 \\u0625\\u0634\\u0627\\u0631\\u0629 \\u0645\\u0648\\u062C\\u0629 \\u0643\\u0628\\u064A\\u0631\\u0629 \\u0648\\u0628\\u062A\\u0637\\u0644\\u0628 \\u0627\\u0644\\u0643\\u0644 \\u064A\\u0631\\u062C\\u0639*",
    ["*points low, then shows one finger*"] = "*\\u0628\\u062A\\u0623\\u0634\\u0631 \\u0644\\u062A\\u062D\\u062A \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u0625\\u0635\\u0628\\u0639 \\u0648\\u0627\\u062D\\u062F*",
    ["*raises two fingers: two walkers ahead*"] = "*\\u0628\\u062A\\u0631\\u0641\\u0639 \\u0625\\u0635\\u0628\\u0639\\u064A\\u0646: \\u062A\\u0646\\u064A\\u0646 \\u0642\\u062F\\u0627\\u0645*",
    ["*shows four, then pairs two fingers: team up*"] = "*\\u0628\\u062A\\u0623\\u0634\\u0631 \\u0628\\u0623\\u0631\\u0628\\u0639\\u0629 \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u0625\\u0635\\u0628\\u0639\\u064A\\u0646: \\u0645\\u0639 \\u0628\\u0639\\u0636*",
    ["*shows two fingers, then motions to split them apart*"] = "*\\u0628\\u062A\\u0623\\u0634\\u0631 \\u0628\\u0625\\u0635\\u0628\\u0639\\u064A\\u0646 \\u0648\\u0628\\u062A\\u0641\\u0631\\u0642 \\u0628\\u064A\\u0646\\u0647\\u0645*",
    ["*signals two contacts near each other*"] = "*\\u0628\\u062A\\u0623\\u0634\\u0631: \\u062A\\u0646\\u064A\\u0646 \\u0642\\u0631\\u0627\\u0628 \\u0645\\u0646 \\u0628\\u0639\\u0636*",
    ["*two fingers, then a chopping motion: split them*"] = "*\\u0625\\u0635\\u0628\\u0639\\u064A\\u0646 \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u062A\\u0634\\u0642 \\u0627\\u0644\\u0647\\u0648\\u0627: \\u0641\\u0631\\u0642\\u0648\\u0647\\u0645*",
    ["A Kentucky mile always was longer than it looks."] = "\\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u0647\\u0648\\u0646 \\u062F\\u0627\\u064A\\u0645\\u0627\\u064B \\u0623\\u0637\\u0648\\u0644 \\u0645\\u0645\\u0627 \\u0628\\u064A\\u0628\\u064A\\u0651\\u0646.",
    ["All right. I will come with you."] = "\\u0645\\u0627\\u0634\\u064A\\u060C \\u062C\\u0627\\u064A\\u0629 \\u0645\\u0639\\u0643.",
    ["At this rate, the tires will retire before we do."] = "\\u0647\\u064A\\u0643 \\u0627\\u0644\\u062F\\u0648\\u0627\\u0644\\u064A\\u0628 \\u0628\\u062A\\u062A\\u0642\\u0627\\u0639\\u062F \\u0642\\u0628\\u0644\\u0646\\u0627.",
    ["Attention! Free brains at the Muldraugh water tower!"] = "\\u064A\\u0627 \\u062C\\u0645\\u0627\\u0639\\u0629! \\u0641\\u064A \\u0645\\u062E\\u0627\\u062E \\u0628\\u0628\\u0644\\u0627\\u0634 \\u0639\\u0646\\u062F \\u062E\\u0632\\u0627\\u0646 \\u0627\\u0644\\u0645\\u064A!",
    ["Back away from it!"] = "\\u0644\\u0648\\u0631\\u0627 \\u0639\\u0646\\u0647!",
    ["Back up! This one's too close!"] = "\\u0644\\u0648\\u0631\\u0627! \\u0647\\u0627\\u062F \\u0642\\u0631\\u064A\\u0628 \\u0643\\u062A\\u064A\\u0631!",
    ["Behind you! It's the tax man!"] = "\\u0648\\u0631\\u0627\\u0643! \\u0625\\u062C\\u0627 \\u062A\\u0628\\u0639 \\u0627\\u0644\\u0636\\u0631\\u0627\\u064A\\u0628!",
    ["Big pack! Stop fighting and move!"] = "\\u0643\\u062A\\u064A\\u0631! \\u062E\\u0644\\u0635 \\u0642\\u062A\\u0627\\u0644 \\u0648\\u064A\\u0644\\u0627!",
    ["Break contact with the group!"] = "\\u0627\\u0628\\u0639\\u062F\\u0648\\u0627 \\u0639\\u0646 \\u0647\\u0627\\u0644\\u062C\\u0645\\u0627\\u0639\\u0629!",
    ["Can somebody get me a blanket? I can't get warm."] = "\\u062D\\u062F\\u0627 \\u064A\\u062C\\u0628\\u0644\\u064A \\u062D\\u0631\\u0627\\u0645\\u061F \\u0645\\u0627 \\u0639\\u0645 \\u0627\\u062F\\u0641\\u0649.",
    ["Can't verify the whole room."] = "\\u0645\\u0627 \\u0634\\u0641\\u062A \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0643\\u0644\\u0647\\u0627.",
    ["Contact - one infected."] = "\\u0641\\u064A \\u0648\\u0627\\u062D\\u062F \\u0642\\u0631\\u064A\\u0628.",
    ["Contact. One zombie."] = "\\u0641\\u064A \\u0648\\u0627\\u062D\\u062F.",
    ["Crowd of deadheads. Watch the sides."] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0643\\u0628\\u064A\\u0631\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0648\\u062A\\u0649. \\u0627\\u0646\\u062A\\u0628\\u0647 \\u0639\\u0627\\u0644\\u062C\\u0648\\u0627\\u0646\\u0628.",
    ["Crowd of zombies ahead."] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0643\\u0628\\u064A\\u0631\\u0629 \\u0645\\u0646\\u0647\\u0645 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627.",
    ["Dashboard clock's wrong. Still making better progress than us."] = "\\u0633\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0633\\u064A\\u0627\\u0631\\u0629 \\u063A\\u0644\\u0637\\u060C \\u0648\\u0645\\u0639 \\u0647\\u064A\\u0643 \\u0645\\u0627\\u0634\\u064A\\u0629 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646\\u0627.",
    ["Do we need gas, or a written invitation?"] = "\\u0628\\u062F\\u0646\\u0627 \\u0628\\u0646\\u0632\\u064A\\u0646 \\u0648\\u0644\\u0627 \\u062F\\u0639\\u0648\\u0629 \\u0645\\u0643\\u062A\\u0648\\u0628\\u0629\\u061F",
    ["Don't cry. Hey. Don't cry. You'll make me cry, and I don't have time."] = "\\u0644\\u0627 \\u062A\\u0628\\u0643\\u064A. \\u0647\\u064A\\u0647\\u060C \\u0644\\u0627 \\u062A\\u0628\\u0643\\u064A. \\u0628\\u062A\\u0628\\u0643\\u064A\\u0646\\u064A\\u060C \\u0648\\u0645\\u0627 \\u0645\\u0639\\u064A \\u0648\\u0642\\u062A.",
    ["Don't leave me alone tonight. Please."] = "\\u0645\\u0627 \\u062A\\u062A\\u0631\\u0643\\u0646\\u064A \\u0644\\u062D\\u0627\\u0644\\u064A \\u0627\\u0644\\u0644\\u064A\\u0644\\u0629. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643.",
    ["Don't sit so close. I don't want it to be you next."] = "\\u0645\\u0627 \\u062A\\u0642\\u0639\\u062F \\u0642\\u0631\\u064A\\u0628 \\u0643\\u062A\\u064A\\u0631. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u062A\\u0643\\u0648\\u0646 \\u0625\\u0646\\u062A \\u0627\\u0644\\u062C\\u0627\\u064A.",
    ["Don't worry about me. Okay. Worry a little."] = "\\u0645\\u0627 \\u062A\\u0642\\u0644\\u0642 \\u0639\\u0644\\u064A\\u064A. \\u0637\\u064A\\u0628\\u060C \\u0627\\u0642\\u0644\\u0642 \\u0634\\u0648\\u064A.",
    ["Dry county jokes hit different when clean water's scarce."] = "\\u0646\\u0643\\u062A\\u0629 \\u0627\\u0644\\u0639\\u0637\\u0634 \\u0628\\u062A\\u0635\\u064A\\u0631 \\u0645\\u0648\\u062C\\u0639\\u0629 \\u0644\\u0645\\u0627 \\u0627\\u0644\\u0645\\u064A \\u0628\\u062A\\u0642\\u0644.",
    ["Easy there. I bruise same as you."] = "\\u0634\\u0648\\u064A \\u0634\\u0648\\u064A\\u060C \\u0623\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646 \\u0628\\u062A\\u0648\\u062C\\u0639.",
    ["Engine's not gonna fix itself. Neither is my mood."] = "\\u0627\\u0644\\u0645\\u062D\\u0631\\u0643 \\u0645\\u0627 \\u0631\\u062D \\u064A\\u0635\\u0644\\u062D \\u062D\\u0627\\u0644\\u0647\\u060C \\u0648\\u0644\\u0627 \\u0645\\u0632\\u0627\\u062C\\u064A.",
    ["Evening already. Keep an eye on the shadows."] = "\\u0635\\u0627\\u0631 \\u0627\\u0644\\u0645\\u0633\\u0627. \\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0639\\u0627\\u0644\\u0636\\u0644\\u0627\\u0644.",
    ["Every tree we pass, my brain asks what if."] = "\\u0643\\u0644 \\u0634\\u062C\\u0631\\u0629 \\u0645\\u0646\\u0645\\u0631 \\u062D\\u062F\\u0647\\u0627\\u060C \\u0631\\u0627\\u0633\\u064A \\u0628\\u064A\\u0633\\u0623\\u0644: \\u0637\\u064A\\u0628 \\u0648\\u0625\\u0630\\u0627\\u061F",
    ["Feels almost like an ordinary day. Don't tell anybody."] = "\\u062D\\u0627\\u0633\\u0629 \\u0625\\u0646\\u0647 \\u0646\\u0647\\u0627\\u0631 \\u0639\\u0627\\u062F\\u064A \\u062A\\u0642\\u0631\\u064A\\u0628\\u0627\\u064B. \\u0644\\u0627 \\u062A\\u0642\\u0648\\u0644 \\u0644\\u062D\\u062F\\u0627.",
    ["Four walkers, give or take one."] = "\\u0623\\u0631\\u0628\\u0639\\u0629 \\u062A\\u0642\\u0631\\u064A\\u0628\\u0627\\u064B\\u060C \\u0632\\u0627\\u064A\\u062F \\u0646\\u0627\\u0642\\u0635 \\u0648\\u0627\\u062D\\u062F.",
    ["Four walkers. Nobody goes in alone."] = "\\u0623\\u0631\\u0628\\u0639\\u0629. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0641\\u0648\\u062A \\u0644\\u062D\\u0627\\u0644\\u0647.",
    ["Funny how a room can feel crowded with nobody in it."] = "\\u063A\\u0631\\u064A\\u0628 \\u0643\\u064A\\u0641 \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0628\\u062A\\u062D\\u0633\\u0647\\u0627 \\u0645\\u0644\\u064A\\u0627\\u0646\\u0629 \\u0648\\u0645\\u0627 \\u0641\\u064A\\u0647\\u0627 \\u062D\\u062F\\u0627.",
    ["Funny thing, the end of the world. Still got chores."] = "\\u063A\\u0631\\u064A\\u0628\\u0629 \\u0646\\u0647\\u0627\\u064A\\u0629 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627. \\u0648\\u0627\\u0644\\u0634\\u063A\\u0644 \\u0644\\u0633\\u0627 \\u0645\\u0627 \\u062E\\u0644\\u0635.",
    ["Give it a year, maybe we'll have the only porch light in Kentucky."] = "\\u064A\\u0645\\u0643\\u0646 \\u0628\\u0639\\u062F \\u0633\\u0646\\u0629 \\u064A\\u0643\\u0648\\u0646 \\u0639\\u0646\\u0627 \\u0622\\u062E\\u0631 \\u0636\\u0648 \\u0628\\u0628\\u0644\\u0643\\u0648\\u0646\\u0629 \\u0628\\u0627\\u0644\\u0628\\u0644\\u062F \\u0643\\u0644\\u0647\\u0627.",
    ["Go down!"] = "\\u0645\\u0648\\u062A!",
    ["Good morning. It is almost strange how normal that sounds."] = "\\u0635\\u0628\\u0627\\u062D \\u0627\\u0644\\u062E\\u064A\\u0631. \\u063A\\u0631\\u064A\\u0628 \\u0643\\u064A\\u0641 \\u0644\\u0633\\u0627 \\u0628\\u062A\\u0637\\u0644\\u0639 \\u0639\\u0627\\u062F\\u064A\\u0629.",
    ["Good morning. Let's see what today gives us."] = "\\u0635\\u0628\\u0627\\u062D \\u0627\\u0644\\u062E\\u064A\\u0631. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0634\\u0648\\u0641 \\u0634\\u0648 \\u0645\\u062E\\u0628\\u0649 \\u0644\\u0646\\u0627 \\u0627\\u0644\\u064A\\u0648\\u0645.",
    ["Good news, no commute. Bad news, the reason why."] = "\\u0627\\u0644\\u062E\\u0628\\u0631 \\u0627\\u0644\\u062D\\u0644\\u0648 \\u0645\\u0627 \\u0641\\u064A \\u0645\\u0648\\u0627\\u0635\\u0644\\u0627\\u062A. \\u0627\\u0644\\u062E\\u0628\\u0631 \\u0627\\u0644\\u0648\\u062D\\u0634 \\u0644\\u064A\\u0634 \\u0645\\u0627 \\u0641\\u064A.",
    ["Got loose!"] = "\\u0641\\u0644\\u062A\\u062A!",
    ["HEY! Is that a Spiffo's coupon on the ground?!"] = "\\u0647\\u064A\\u0647! \\u0647\\u0627\\u062F \\u0643\\u0648\\u0628\\u0648\\u0646 \\u062E\\u0635\\u0645 \\u0639\\u0627\\u0644\\u0623\\u0631\\u0636\\u061F!",
    ["Hard to picture a Derby with nobody in the stands."] = "\\u0635\\u0639\\u0628 \\u0623\\u062A\\u062E\\u064A\\u0644 \\u0627\\u0644\\u0645\\u062F\\u0631\\u062C\\u0627\\u062A \\u0641\\u0627\\u0636\\u064A\\u0629 \\u0647\\u064A\\u0643.",
    ["Here comes the rain. Watch the corners; hearing will be worse."] = "\\u0625\\u062C\\u062A \\u0627\\u0644\\u0634\\u062A\\u0627. \\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0639\\u0627\\u0644\\u0632\\u0648\\u0627\\u064A\\u0627\\u060C \\u0645\\u0627 \\u0631\\u062D \\u0646\\u0633\\u0645\\u0639 \\u0645\\u0646\\u064A\\u062D.",
    ["Hey! Somebody out there misses you! Go find them!"] = "\\u0647\\u064A\\u0647! \\u0641\\u064A \\u062D\\u062F\\u0627 \\u0645\\u0634\\u062A\\u0642\\u0644\\u0643 \\u0647\\u0648\\u0646\\u064A\\u0643! \\u0631\\u0648\\u062D \\u062F\\u0648\\u0651\\u0631 \\u0639\\u0644\\u064A\\u0647!",
    ["Hold my hand. I can't feel it anymore, but hold it anyway."] = "\\u0645\\u0633\\u0643\\u0646\\u064A \\u0625\\u064A\\u062F\\u064A. \\u0645\\u0627 \\u0639\\u0645 \\u062D\\u0633\\u0647\\u0627\\u060C \\u0628\\u0633 \\u0627\\u0645\\u0633\\u0643\\u0647\\u0627.",
    ["Horde ahead!"] = "\\u0645\\u0648\\u062C\\u0629 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627!",
    ["Horde! Stay together and follow me out."] = "\\u0645\\u0648\\u062C\\u0629! \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0633\\u0648\\u0627 \\u0648\\u062A\\u0639\\u0627\\u0644 \\u0648\\u0631\\u0627\\u064A.",
    ["How long do you think I've got? No. Don't answer that."] = "\\u0642\\u062F\\u064A\\u0634 \\u0628\\u0631\\u0623\\u064A\\u0643 \\u0636\\u0627\\u064A\\u0644 \\u0644\\u064A\\u061F \\u0644\\u0623\\u060C \\u0645\\u0627 \\u062A\\u062C\\u0627\\u0648\\u0628.",
    ["Huge horde in front of us."] = "\\u0645\\u0648\\u062C\\u0629 \\u0643\\u0628\\u064A\\u0631\\u0629 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627.",
    ["I appreciate it. I'll keep it ready."] = "\\u064A\\u0633\\u0644\\u0645\\u0648. \\u0631\\u062D \\u062E\\u0644\\u064A\\u0647\\u0627 \\u062C\\u0627\\u0647\\u0632\\u0629.",
    ["I can still feel my fingers. That's good, right? That's good."] = "\\u0644\\u0633\\u0627 \\u062D\\u0627\\u0633\\u0629 \\u0628\\u0623\\u0635\\u0627\\u0628\\u0639\\u064A. \\u0645\\u0646\\u064A\\u062D\\u060C \\u0645\\u0648\\u061F \\u0645\\u0646\\u064A\\u062D.",
    ["I can taste metal. Nothing tastes right anymore."] = "\\u0637\\u0639\\u0645\\u0629 \\u062D\\u062F\\u064A\\u062F \\u0628\\u062A\\u0645\\u064A. \\u0648\\u0644\\u0627 \\u0634\\u064A \\u0637\\u0639\\u0645\\u062A\\u0647 \\u0645\\u062A\\u0644 \\u0642\\u0628\\u0644.",
    ["I can't remember my mother's face. I had it this morning."] = "\\u0645\\u0627 \\u0639\\u0645 \\u0627\\u062A\\u0630\\u0643\\u0631 \\u0648\\u062C\\u0647 \\u0623\\u0645\\u064A. \\u0627\\u0644\\u0635\\u0628\\u062D \\u0643\\u0646\\u062A \\u0645\\u062A\\u0630\\u0643\\u0631\\u062A\\u0647.",
    ["I could walk faster than this. Sitting down."] = "\\u0628\\u0645\\u0634\\u064A \\u0623\\u0633\\u0631\\u0639 \\u0645\\u0646 \\u0647\\u064A\\u0643 \\u0648\\u0623\\u0646\\u0627 \\u0642\\u0627\\u0639\\u062F\\u0629.",
    ["I count at least six."] = "\\u0639\\u062F\\u0651\\u064A\\u062A \\u0633\\u062A\\u0629 \\u0639\\u0627\\u0644\\u0623\\u0642\\u0644.",
    ["I count two."] = "\\u0639\\u062F\\u0651\\u064A\\u062A \\u062A\\u0646\\u064A\\u0646.",
    ["I don't like what this does to our hearing."] = "\\u0645\\u0648 \\u0639\\u0627\\u062C\\u0628\\u0646\\u064A \\u0634\\u0648 \\u0639\\u0645 \\u062A\\u0639\\u0645\\u0644 \\u0628\\u0633\\u0645\\u0639\\u0646\\u0627.",
    ["I don't wanna lose myself. Please. I don't want to forget who I am."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0636\\u064A\\u0639 \\u062D\\u0627\\u0644\\u064A. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643\\u060C \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0646\\u0633\\u0649 \\u0645\\u064A\\u0646 \\u0623\\u0646\\u0627.",
    ["I don't want to die out here. Not like this."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0645\\u0648\\u062A \\u0647\\u0648\\u0646. \\u0645\\u0648 \\u0647\\u064A\\u0643.",
    ["I don't want to hurt anybody. Promise me I won't hurt anybody."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0623\\u0630\\u064A \\u062D\\u062F\\u0627. \\u0648\\u0639\\u062F\\u0646\\u064A \\u0625\\u0646\\u064A \\u0645\\u0627 \\u0631\\u062D \\u0623\\u0630\\u064A \\u062D\\u062F\\u0627.",
    ["I feel cold. Why am I so cold? It's the middle of summer."] = "\\u0628\\u0631\\u062F\\u0627\\u0646\\u0629. \\u0644\\u064A\\u0634 \\u0628\\u0631\\u062F\\u0627\\u0646\\u0629 \\u0647\\u064A\\u0643 \\u0648\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0635\\u064A\\u0641\\u061F",
    ["I had a dog once. His name was... I can't remember his name."] = "\\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u064A \\u0643\\u0644\\u0628 \\u0645\\u0631\\u0629. \\u0627\\u0633\\u0645\\u0647 \\u0643\\u0627\\u0646... \\u0646\\u0633\\u064A\\u062A \\u0627\\u0633\\u0645\\u0647.",
    ["I keep looking at it. Like if I stare long enough, it'll go away."] = "\\u0636\\u0644\\u0646\\u064A \\u0627\\u062A\\u0637\\u0644\\u0639 \\u0641\\u064A\\u0647\\u0627\\u060C \\u0643\\u0623\\u0646 \\u0625\\u0630\\u0627 \\u0637\\u0648\\u0644\\u062A \\u0628\\u062A\\u0631\\u0648\\u062D.",
    ["I keep losing minutes. Did I already say that?"] = "\\u0639\\u0645 \\u0636\\u064A\\u0639 \\u062F\\u0642\\u0627\\u064A\\u0642. \\u0642\\u0644\\u062A \\u0647\\u0627\\u0644\\u062D\\u0643\\u064A \\u0642\\u0628\\u0644\\u061F",
    ["I keep thinking about my mom's kitchen. Isn't that stupid?"] = "\\u0639\\u0645 \\u0641\\u0643\\u0631 \\u0628\\u0645\\u0637\\u0628\\u062E \\u0623\\u0645\\u064A. \\u0645\\u0648 \\u0633\\u062E\\u064A\\u0641\\u0629 \\u0647\\u0627\\u0644\\u0634\\u063A\\u0644\\u0629\\u061F",
    ["I see one. Keep your eyes on it."] = "\\u0634\\u0627\\u064A\\u0641\\u0629 \\u0648\\u0627\\u062D\\u062F. \\u062E\\u0644\\u064A \\u0639\\u064A\\u0646\\u0643 \\u0639\\u0644\\u064A\\u0647.",
    ["I understand. Take care."] = "\\u0641\\u0647\\u0645\\u062A. \\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0639\\u0644\\u0649 \\u062D\\u0627\\u0644\\u0643.",
    ["I was bitten. We need to decide what happens next."] = "\\u0639\\u0636\\u0648\\u0646\\u064A. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u0642\\u0631\\u0631 \\u0634\\u0648 \\u0628\\u062F\\u0646\\u0627 \\u0646\\u0639\\u0645\\u0644.",
    ["I'd trade every dollar in this county for cold sweet tea."] = "\\u0628\\u062F\\u0641\\u0639 \\u0643\\u0644 \\u0645\\u0635\\u0627\\u0631\\u064A \\u0627\\u0644\\u0628\\u0644\\u062F \\u0645\\u0642\\u0627\\u0628\\u0644 \\u0643\\u0627\\u0633\\u0629 \\u0634\\u0627\\u064A \\u0628\\u0627\\u0631\\u062F.",
    ["I'll handle this one!"] = "\\u0647\\u0627\\u062F \\u0639\\u0644\\u064A\\u064A!",
    ["I'll just stand here and age, then."] = "\\u062A\\u0645\\u0627\\u0645\\u060C \\u0628\\u0648\\u0642\\u0641 \\u0647\\u0648\\u0646 \\u0648\\u0628\\u062E\\u062A\\u064A\\u0631.",
    ["I'll keep looking. You keep watch."] = "\\u0623\\u0646\\u0627 \\u0628\\u0643\\u0645\\u0644 \\u062A\\u062F\\u0648\\u064A\\u0631\\u060C \\u0648\\u0625\\u0646\\u062A \\u062E\\u0644\\u064A\\u0643 \\u0645\\u0646\\u062A\\u0628\\u0647.",
    ["I'll take care of it. And I'll use it when it counts."] = "\\u0631\\u062D \\u062F\\u064A\\u0631\\u0647\\u0627 \\u0628\\u0627\\u0644\\u064A. \\u0648\\u0628\\u0633\\u062A\\u0639\\u0645\\u0644\\u0647\\u0627 \\u0644\\u0645\\u0627 \\u062A\\u0644\\u0632\\u0645.",
    ["I'm burning up and freezing at the same time."] = "\\u0639\\u0645 \\u0648\\u0644\\u0639 \\u0648\\u0628\\u0631\\u062F \\u0628\\u0646\\u0641\\u0633 \\u0627\\u0644\\u0648\\u0642\\u062A.",
    ["I'm counting the turns, in case we need to come back fast."] = "\\u0639\\u0645 \\u0639\\u062F\\u0651 \\u0627\\u0644\\u0645\\u0641\\u0627\\u0631\\u0642\\u060C \\u0628\\u0644\\u0643\\u064A \\u0627\\u062D\\u062A\\u062C\\u0646\\u0627 \\u0646\\u0631\\u062C\\u0639 \\u0628\\u0633\\u0631\\u0639\\u0629.",
    ["I'm engaging. Don't get surrounded!"] = "\\u0623\\u0646\\u0627 \\u062F\\u0627\\u062E\\u0644\\u0629 \\u0639\\u0644\\u064A\\u0647\\u0645. \\u0645\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0647\\u0645 \\u064A\\u0637\\u0648\\u0642\\u0648\\u0643!",
    ["I'm not ready. I had plans. Stupid little plans, but they were mine."] = "\\u0623\\u0646\\u0627 \\u0645\\u0648 \\u062C\\u0627\\u0647\\u0632\\u0629. \\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u064A \\u062E\\u0637\\u0637 \\u0635\\u063A\\u064A\\u0631\\u0629\\u060C \\u0628\\u0633 \\u0643\\u0627\\u0646\\u062A \\u0625\\u0644\\u064A.",
    ["I'm scared. I'm really, really scared."] = "\\u0623\\u0646\\u0627 \\u062E\\u0627\\u064A\\u0641\\u0629. \\u062E\\u0627\\u064A\\u0641\\u0629 \\u0643\\u062A\\u064A\\u0631.",
    ["I'm so tired. I'm so tired, and I'm so scared."] = "\\u062A\\u0639\\u0628\\u0627\\u0646\\u0629 \\u0643\\u062A\\u064A\\u0631. \\u062A\\u0639\\u0628\\u0627\\u0646\\u0629 \\u0648\\u062E\\u0627\\u064A\\u0641\\u0629.",
    ["I'm sorry. I'm sorry for all of it."] = "\\u0633\\u0627\\u0645\\u062D\\u0646\\u064A. \\u0633\\u0627\\u0645\\u062D\\u0646\\u064A \\u0639\\u0644\\u0649 \\u0643\\u0644 \\u0634\\u064A.",
    ["I've counted every crack in the windshield. Want the report?"] = "\\u0639\\u062F\\u0651\\u064A\\u062A \\u0643\\u0644 \\u0634\\u0642 \\u0628\\u0627\\u0644\\u0632\\u062C\\u0627\\u062C. \\u0628\\u062F\\u0643 \\u0627\\u0644\\u062A\\u0642\\u0631\\u064A\\u0631\\u061F",
    ["I've got at least half a dozen."] = "\\u0639\\u0646\\u062F\\u064A \\u0633\\u062A\\u0629 \\u0639\\u0627\\u0644\\u0623\\u0642\\u0644.",
    ["I've got two moving together."] = "\\u0641\\u064A \\u062A\\u0646\\u064A\\u0646 \\u0645\\u0627\\u0634\\u064A\\u064A\\u0646 \\u0633\\u0648\\u0627.",
    ["If I start acting strange, you tell me. Promise me."] = "\\u0625\\u0630\\u0627 \\u0635\\u0631\\u062A \\u063A\\u0631\\u064A\\u0628\\u0629\\u060C \\u062E\\u0628\\u0631\\u0646\\u064A. \\u0648\\u0639\\u062F\\u0646\\u064A.",
    ["If anybody asks, I'm on break. Have been since July."] = "\\u0625\\u0630\\u0627 \\u062D\\u062F\\u0627 \\u0633\\u0623\\u0644\\u060C \\u0623\\u0646\\u0627 \\u0628\\u0625\\u062C\\u0627\\u0632\\u0629 \\u0645\\u0646 \\u062A\\u0645\\u0648\\u0632.",
    ["If the army's holding the county line, they're doing it real quiet."] = "\\u0625\\u0630\\u0627 \\u0627\\u0644\\u062C\\u064A\\u0634 \\u0644\\u0633\\u0627 \\u0639\\u0627\\u0644\\u062D\\u062F\\u0648\\u062F\\u060C \\u0641\\u0647\\u0648 \\u0633\\u0627\\u0643\\u062A \\u0643\\u062A\\u064A\\u0631.",
    ["If we split up, keep your voice low and close."] = "\\u0625\\u0630\\u0627 \\u062A\\u0641\\u0631\\u0642\\u0646\\u0627\\u060C \\u062E\\u0644\\u064A \\u0635\\u0648\\u062A\\u0643 \\u0648\\u0627\\u0637\\u064A \\u0648\\u0642\\u0631\\u064A\\u0628.",
    ["If we stop, I'll take the side you're not watching."] = "\\u0625\\u0630\\u0627 \\u0648\\u0642\\u0641\\u0646\\u0627\\u060C \\u0628\\u0627\\u062E\\u062F \\u0627\\u0644\\u062C\\u0647\\u0629 \\u064A\\u0644\\u064A \\u0645\\u0627 \\u0639\\u0645 \\u062A\\u0634\\u0648\\u0641\\u0647\\u0627.",
    ["If you ever find my family, tell them I tried. Tell them I tried so hard."] = "\\u0625\\u0630\\u0627 \\u0634\\u0641\\u062A \\u0623\\u0647\\u0644\\u064A \\u064A\\u0648\\u0645\\u0627\\u064B\\u060C \\u0642\\u0648\\u0644\\u0647\\u0645 \\u062D\\u0627\\u0648\\u0644\\u062A. \\u062D\\u0627\\u0648\\u0644\\u062A \\u0643\\u062A\\u064A\\u0631.",
    ["If you see trouble first, say it plain."] = "\\u0625\\u0630\\u0627 \\u0634\\u0641\\u062A \\u0634\\u064A \\u0642\\u0628\\u0644\\u064A\\u060C \\u0642\\u0648\\u0644\\u0647 \\u0628\\u0635\\u0631\\u0627\\u062D\\u0629.",
    ["Is it cold in here, or is it just me? It's just me, isn't it."] = "\\u0641\\u064A \\u0628\\u0631\\u062F \\u0647\\u0648\\u0646 \\u0648\\u0644\\u0627 \\u0623\\u0646\\u0627 \\u0628\\u0633\\u061F \\u0623\\u0646\\u0627 \\u0628\\u0633\\u060C \\u0645\\u0648 \\u0647\\u064A\\u0643\\u061F",
    ["Is this a strategy, or are we lost?"] = "\\u0647\\u0627\\u064A \\u062E\\u0637\\u0629 \\u0648\\u0644\\u0627 \\u0636\\u0639\\u0646\\u0627\\u061F",
    ["It is getting dark. I'd rather have everyone inside."] = "\\u0639\\u0645 \\u062A\\u0639\\u062A\\u0645. \\u0628\\u0641\\u0636\\u0651\\u0644 \\u0627\\u0644\\u0643\\u0644 \\u064A\\u0643\\u0648\\u0646 \\u062C\\u0648\\u0651\\u0627.",
    ["It will be dark soon. Time to think about shelter."] = "\\u0642\\u0631\\u0651\\u0628\\u062A \\u062A\\u0639\\u062A\\u0645. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u0641\\u0643\\u0631 \\u0648\\u064A\\u0646 \\u0628\\u062F\\u0646\\u0627 \\u0646\\u0644\\u062A\\u062C\\u064A.",
    ["It's getting dark in my head. Like lights going out, room by room."] = "\\u0639\\u0645 \\u062A\\u0639\\u062A\\u0645 \\u0628\\u0631\\u0627\\u0633\\u064A. \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0636\\u0648 \\u064A\\u0644\\u064A \\u0639\\u0645 \\u064A\\u0646\\u0637\\u0641\\u064A \\u063A\\u0631\\u0641\\u0629 \\u063A\\u0631\\u0641\\u0629.",
    ["It's just a bite. People survive bites. Right? Somebody tell me people survive bites."] = "\\u0639\\u0636\\u0629 \\u0648\\u0628\\u0633. \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0628\\u062A\\u0639\\u064A\\u0634 \\u0628\\u0639\\u062F \\u0627\\u0644\\u0639\\u0636\\u060C \\u0645\\u0648\\u061F \\u062D\\u062F\\u0627 \\u064A\\u0642\\u0644\\u064A \\u0645\\u0648 \\u0647\\u064A\\u0643.",
    ["Just one in sight. Watch yourself."] = "\\u0628\\u0633 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0628\\u064A\\u0646. \\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643.",
    ["Just one zombie in sight."] = "\\u0628\\u0633 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0628\\u064A\\u0646.",
    ["Keep an ear on the doors. I'll mind this side."] = "\\u062E\\u0644\\u064A \\u0633\\u0645\\u0639\\u0643 \\u0639\\u0627\\u0644\\u0628\\u0648\\u0627\\u0628\\u060C \\u0648\\u0623\\u0646\\u0627 \\u0628\\u0627\\u062E\\u062F \\u0647\\u0627\\u0644\\u062C\\u0647\\u0629.",
    ["Keep going. I've got your back."] = "\\u0643\\u0645\\u0651\\u0644\\u060C \\u0623\\u0646\\u0627 \\u062D\\u0627\\u0645\\u064A\\u0629 \\u0636\\u0647\\u0631\\u0643.",
    ["Keeping busy at the end of the world. Mama would be proud."] = "\\u0645\\u0634\\u063A\\u0648\\u0644\\u064A\\u0646 \\u0628\\u0622\\u062E\\u0631 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627. \\u0623\\u0645\\u064A \\u0643\\u0627\\u0646\\u062A \\u0631\\u062D \\u062A\\u0641\\u062A\\u062E\\u0631.",
    ["Kentucky weather never cared who was left to complain about it."] = "\\u0627\\u0644\\u0637\\u0642\\u0633 \\u0647\\u0648\\u0646 \\u0639\\u0645\\u0631\\u0647 \\u0645\\u0627 \\u0633\\u0623\\u0644 \\u0645\\u064A\\u0646 \\u0636\\u0627\\u064A\\u0644 \\u0644\\u064A\\u0634\\u0643\\u064A.",
    ["Knox County never looked this empty on a weekday."] = "\\u0639\\u0645\\u0631\\u0647\\u0627 \\u0627\\u0644\\u0628\\u0644\\u062F \\u0645\\u0627 \\u0643\\u0627\\u0646\\u062A \\u0641\\u0627\\u0636\\u064A\\u0629 \\u0647\\u064A\\u0643 \\u0628\\u0646\\u0635 \\u0627\\u0644\\u062C\\u0645\\u0639\\u0629.",
    ["Let's count heads before we settle in for the night."] = "\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0639\\u062F\\u0651 \\u062D\\u0627\\u0644\\u0646\\u0627 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0631\\u062A\\u0627\\u062D \\u0647\\u0627\\u0644\\u0644\\u064A\\u0644\\u0629.",
    ["Look over there! A mule in a hospital gown!"] = "\\u0634\\u0648\\u0641 \\u0647\\u0648\\u0646\\u064A\\u0643! \\u0628\\u063A\\u0644 \\u0644\\u0627\\u0628\\u0633 \\u0631\\u0648\\u0628 \\u0645\\u0633\\u062A\\u0634\\u0641\\u0649!",
    ["Look, a way out! For you! Over there! Please!"] = "\\u0634\\u0648\\u0641\\u060C \\u0641\\u064A \\u0637\\u0631\\u064A\\u0642! \\u0625\\u0644\\u0643 \\u0625\\u0646\\u062A! \\u0647\\u0648\\u0646\\u064A\\u0643! \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643!",
    ["Mass of dead ahead. Do not go that way."] = "\\u0641\\u064A \\u0646\\u0627\\u0633 \\u0645\\u064A\\u062A\\u064A\\u0646 \\u0643\\u062A\\u064A\\u0631 \\u0642\\u062F\\u0627\\u0645. \\u0645\\u0627 \\u0646\\u0631\\u0648\\u062D \\u0645\\u0646 \\u0647\\u0648\\u0646.",
    ["Maybe a radio's still promising help. Bless its heart."] = "\\u064A\\u0645\\u0643\\u0646 \\u0641\\u064A \\u0631\\u0627\\u062F\\u064A\\u0648 \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u064A\\u0648\\u0639\\u062F \\u0628\\u0627\\u0644\\u0645\\u0633\\u0627\\u0639\\u062F\\u0629. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u0639\\u064A\\u0646\\u0647.",
    ["Maybe it didn't break the skin. Maybe. Maybe."] = "\\u064A\\u0645\\u0643\\u0646 \\u0645\\u0627 \\u0627\\u062E\\u062A\\u0631\\u0642\\u062A \\u0627\\u0644\\u062C\\u0644\\u062F. \\u064A\\u0645\\u0643\\u0646.",
    ["Mind the cars. Something always hides behind one."] = "\\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0639\\u0627\\u0644\\u0633\\u064A\\u0627\\u0631\\u0627\\u062A\\u060C \\u062F\\u0627\\u064A\\u0645\\u0627\\u064B \\u0641\\u064A \\u0634\\u064A \\u0645\\u062E\\u0628\\u0649 \\u0648\\u0631\\u0627\\u0647\\u0627.",
    ["Mind the mess. Civilization left in a hurry."] = "\\u0645\\u0627 \\u062A\\u062F\\u0642\\u0642 \\u0639\\u0627\\u0644\\u0641\\u0648\\u0636\\u0649. \\u0627\\u0644\\u062D\\u0636\\u0627\\u0631\\u0629 \\u0631\\u0627\\u062D\\u062A \\u0628\\u0639\\u062C\\u0644\\u0629.",
    ["Move back and make it follow!"] = "\\u0627\\u0631\\u062C\\u0639 \\u0644\\u0648\\u0631\\u0627 \\u0648\\u062E\\u0644\\u064A\\u0647 \\u064A\\u0644\\u062D\\u0642\\u0643!",
    ["Multiple contacts."] = "\\u0641\\u064A \\u0643\\u062A\\u064A\\u0631.",
    ["My hands won't stop shaking."] = "\\u0625\\u064A\\u062F\\u064A \\u0645\\u0627 \\u0639\\u0645 \\u062A\\u0647\\u062F\\u0627 \\u0645\\u0646 \\u0627\\u0644\\u0631\\u062C\\u0641\\u0629.",
    ["New day. Same rules: stay sharp and stay alive."] = "\\u0646\\u0647\\u0627\\u0631 \\u062C\\u062F\\u064A\\u062F \\u0648\\u0646\\u0641\\u0633 \\u0627\\u0644\\u0642\\u0635\\u0629: \\u0635\\u062D\\u0635\\u062D \\u0648\\u0636\\u0644 \\u0639\\u0627\\u064A\\u0634.",
    ["New day. We should review our supplies."] = "\\u0646\\u0647\\u0627\\u0631 \\u062C\\u062F\\u064A\\u062F. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u0634\\u0648\\u0641 \\u0634\\u0648 \\u0636\\u0627\\u064A\\u0644 \\u0639\\u0646\\u0627.",
    ["No. Wasn't them. I don't think."] = "\\u0644\\u0623. \\u0645\\u0648 \\u0647\\u0646\\u064A. \\u0639\\u0644\\u0649 \\u0645\\u0627 \\u0628\\u0638\\u0646.",
    ["Nobody gets left behind. Move away from them."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0646\\u062A\\u0631\\u0643. \\u0627\\u0628\\u0639\\u062F\\u0648\\u0627 \\u0639\\u0646\\u0647\\u0645.",
    ["Nobody's paying bills anymore. Silver lining, I reckon."] = "\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u062F\\u0641\\u0639 \\u0641\\u0648\\u0627\\u062A\\u064A\\u0631 \\u0647\\u0644\\u0623. \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0642\\u0644 \\u0647\\u0627\\u064A \\u0645\\u0646\\u064A\\u062D\\u0629.",
    ["Not one. Two of them."] = "\\u0645\\u0648 \\u0648\\u0627\\u062D\\u062F. \\u062A\\u0646\\u064A\\u0646.",
    ["Nothing in this one. Next lid."] = "\\u0645\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0647\\u0648\\u0646. \\u0639\\u0627\\u0644\\u062A\\u0627\\u0646\\u064A.",
    ["Nothing like routine to keep the screaming on the inside."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0631\\u0648\\u062A\\u064A\\u0646 \\u0644\\u064A\\u0636\\u0644 \\u0627\\u0644\\u0635\\u0631\\u0627\\u062E \\u062C\\u0648\\u0627\\u062A\\u064A.",
    ["One body moving. Not alive."] = "\\u0641\\u064A \\u062C\\u0633\\u0645 \\u0639\\u0645 \\u064A\\u062A\\u062D\\u0631\\u0643. \\u0645\\u0648 \\u0639\\u0627\\u064A\\u0634.",
    ["One contact. I'm taking it!"] = "\\u0648\\u0627\\u062D\\u062F \\u0642\\u062F\\u0627\\u0645\\u064A\\u060C \\u0639\\u0644\\u064A\\u064A!",
    ["One deadhead, out ahead."] = "\\u0641\\u064A \\u0648\\u0627\\u062D\\u062F \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627.",
    ["One of them, straight ahead."] = "\\u0641\\u064A \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0647\\u0645 \\u062F\\u063A\\u0631\\u064A \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627.",
    ["One side's all teeth. I'm taking the quieter direction."] = "\\u0647\\u0627\\u0644\\u062C\\u0647\\u0629 \\u0643\\u0644\\u0647\\u0627 \\u0633\\u0646\\u0627\\u0646. \\u0623\\u0646\\u0627 \\u0628\\u0627\\u062E\\u062F \\u0627\\u0644\\u062C\\u0647\\u0629 \\u0627\\u0644\\u0623\\u0647\\u062F\\u0649.",
    ["One walker. I've got it."] = "\\u0648\\u0627\\u062D\\u062F. \\u0639\\u0644\\u064A\\u064A.",
    ["One zombie ahead."] = "\\u0641\\u064A \\u0648\\u0627\\u062D\\u062F \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627.",
    ["One zombie ahead. Stay close to me."] = "\\u0641\\u064A \\u0648\\u0627\\u062D\\u062F \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627. \\u062E\\u0644\\u064A\\u0643 \\u062D\\u062F\\u064A.",
    ["Out of my county!"] = "\\u0628\\u0631\\u0627 \\u0645\\u0646 \\u0628\\u0644\\u062F\\u064A!",
    ["Pair of walkers, front."] = "\\u062A\\u0646\\u064A\\u0646 \\u0642\\u062F\\u0627\\u0645.",
    ["Parked this long, I'd like to know which way we're leaving."] = "\\u0648\\u0642\\u0641\\u0646\\u0627 \\u0643\\u062A\\u064A\\u0631\\u060C \\u0628\\u062F\\u064A \\u0623\\u0639\\u0631\\u0641 \\u0645\\u0646 \\u0648\\u064A\\u0646 \\u0628\\u062F\\u0646\\u0627 \\u0646\\u0637\\u0644\\u0639.",
    ["Picture the mailman showing up. I'd hug him. Then check for bites."] = "\\u062A\\u062E\\u064A\\u0644 \\u064A\\u0637\\u0644\\u0639 \\u0639\\u0644\\u064A\\u0646\\u0627 \\u0645\\u0648\\u0632\\u0639 \\u0627\\u0644\\u0628\\u0631\\u064A\\u062F. \\u0628\\u062D\\u0636\\u0646\\u0647\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u0641\\u062D\\u0635\\u0647 \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0636.",
    ["Pressure's building too fast. I'm giving ground."] = "\\u0627\\u0644\\u0648\\u0636\\u0639 \\u0639\\u0645 \\u064A\\u0636\\u064A\\u0642 \\u0628\\u0633\\u0631\\u0639\\u0629. \\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0627\\u0631\\u062C\\u0639 \\u0644\\u0648\\u0631\\u0627.",
    ["Quiet is good. Quiet is fine. I'll keep an eye out."] = "\\u0627\\u0644\\u0647\\u062F\\u0648\\u0621 \\u0645\\u0646\\u064A\\u062D. \\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0636\\u0644 \\u0645\\u0646\\u062A\\u0628\\u0647\\u0629.",
    ["Rain's setting in. The noise will hide more than our footsteps."] = "\\u0627\\u0644\\u0634\\u062A\\u0627 \\u0646\\u0627\\u0632\\u0644\\u0629. \\u0635\\u0648\\u062A\\u0647\\u0627 \\u0631\\u062D \\u064A\\u063A\\u0637\\u064A \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0635\\u0648\\u062A \\u062E\\u0637\\u0648\\u0627\\u062A\\u0646\\u0627.",
    ["Remember to drink some water when you can."] = "\\u0645\\u0627 \\u062A\\u0646\\u0633\\u0649 \\u062A\\u0634\\u0631\\u0628 \\u0645\\u064A \\u0644\\u0645\\u0627 \\u062A\\u0642\\u062F\\u0631.",
    ["Room clear."] = "\\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0641\\u0627\\u0636\\u064A\\u0629.",
    ["Say my name. Keep saying it, so I don't forget it."] = "\\u0646\\u0627\\u062F\\u064A\\u0646\\u064A \\u0628\\u0627\\u0633\\u0645\\u064A\\u060C \\u062E\\u0644\\u064A \\u062A\\u0639\\u064A\\u062F\\u0647\\u060C \\u062D\\u062A\\u0649 \\u0645\\u0627 \\u0627\\u0646\\u0633\\u0627\\u0647.",
    ["Scenic route again? You spoil me."] = "\\u0643\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0627\\u0644\\u062D\\u0644\\u0648\\u0629\\u061F \\u062F\\u0644\\u0639\\u062A\\u0646\\u064A.",
    ["Seated walker. Waiting doesn't make it harmless."] = "\\u0641\\u064A \\u0648\\u0627\\u062D\\u062F \\u0642\\u0627\\u0639\\u062F. \\u0648\\u0644\\u0648 \\u0642\\u0627\\u0639\\u062F\\u060C \\u0645\\u0627 \\u0628\\u064A\\u0623\\u0645\\u0646.",
    ["Several ahead. Stay together and don't rush."] = "\\u0641\\u064A \\u0643\\u0645 \\u0648\\u0627\\u062D\\u062F \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0633\\u0648\\u0627 \\u0648\\u0645\\u0627 \\u062A\\u0633\\u062A\\u0639\\u062C\\u0644.",
    ["Several walkers. Focus the nearest!"] = "\\u0641\\u064A \\u0643\\u0645 \\u0648\\u0627\\u062D\\u062F. \\u0634\\u0648\\u0641 \\u0627\\u0644\\u0623\\u0642\\u0631\\u0628!",
    ["Single contact ahead - nothing we can't handle."] = "\\u0648\\u0627\\u062D\\u062F \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627. \\u0628\\u0646\\u0642\\u062F\\u0631 \\u0639\\u0644\\u064A\\u0647.",
    ["Single walker, up ahead."] = "\\u0641\\u064A \\u0648\\u0627\\u062D\\u062F \\u0644\\u062D\\u0627\\u0644\\u0647 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627.",
    ["Sitting walker. I'll deal with it."] = "\\u0641\\u064A \\u0648\\u0627\\u062D\\u062F \\u0642\\u0627\\u0639\\u062F. \\u0639\\u0644\\u064A\\u064A.",
    ["Six-plus on us. Withdraw!"] = "\\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0633\\u062A\\u0629 \\u0639\\u0644\\u064A\\u0646\\u0627. \\u0644\\u0648\\u0631\\u0627!",
    ["Slow is fine. Slow is alive."] = "\\u0634\\u0648\\u064A \\u0634\\u0648\\u064A \\u0645\\u0646\\u064A\\u062D. \\u0634\\u0648\\u064A \\u0634\\u0648\\u064A \\u064A\\u0639\\u0646\\u064A \\u0639\\u0627\\u064A\\u0634\\u064A\\u0646.",
    ["Somebody used to have a normal day here."] = "\\u062D\\u062F\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u0647 \\u064A\\u0648\\u0645 \\u0639\\u0627\\u062F\\u064A \\u0647\\u0648\\u0646.",
    ["Take a breath if you need one. I'll keep going."] = "\\u062E\\u062F\\u0644\\u0643 \\u0646\\u0641\\u0633 \\u0625\\u0630\\u0627 \\u0628\\u062F\\u0643\\u060C \\u0648\\u0623\\u0646\\u0627 \\u0628\\u0643\\u0645\\u0644.",
    ["Talk to me. Keep talking. If you talk, I'm still here."] = "\\u0627\\u062D\\u0643\\u064A \\u0645\\u0639\\u064A. \\u0636\\u0644 \\u0627\\u062D\\u0643\\u064A. \\u0637\\u0648\\u0644 \\u0645\\u0627 \\u0639\\u0645 \\u062A\\u062D\\u0643\\u064A\\u060C \\u0623\\u0646\\u0627 \\u0647\\u0648\\u0646.",
    ["That fence collected its toll in dignity."] = "\\u0647\\u0627\\u0644\\u062D\\u064A\\u0637 \\u062E\\u062F \\u0645\\u0646\\u064A \\u0643\\u0631\\u0627\\u0645\\u062A\\u064A.",
    ["That road is lost. Horde."] = "\\u0647\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0627\\u0646\\u062A\\u0647\\u062A. \\u0641\\u064A \\u0645\\u0648\\u062C\\u0629.",
    ["That side's pouring dead people. I'm moving across the flow."] = "\\u0647\\u0627\\u0644\\u062C\\u0647\\u0629 \\u0646\\u0627\\u0632\\u0644 \\u0645\\u0646\\u0647\\u0627 \\u0627\\u0644\\u0645\\u0648\\u062A\\u0649 \\u0646\\u0632\\u0648\\u0644. \\u0628\\u0642\\u0637\\u0639 \\u0645\\u0646 \\u0628\\u064A\\u0646\\u0647\\u0645.",
    ["The dead own that whole block."] = "\\u0627\\u0644\\u0645\\u0648\\u062A\\u0649 \\u0645\\u0627\\u062E\\u062F\\u064A\\u0646 \\u0647\\u0627\\u0644\\u062D\\u0627\\u0631\\u0629 \\u0643\\u0644\\u0647\\u0627.",
    ["The road outside looks calm. I don't trust it yet."] = "\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0628\\u0631\\u0627 \\u0647\\u0627\\u062F\\u064A\\u0629. \\u0628\\u0633 \\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0628\\u0648\\u062B\\u0642 \\u0641\\u064A\\u0647\\u0627.",
    ["The whole street is moving."] = "\\u0627\\u0644\\u0634\\u0627\\u0631\\u0639 \\u0643\\u0644\\u0647 \\u0639\\u0645 \\u064A\\u062A\\u062D\\u0631\\u0643.",
    ["There's a pair up ahead."] = "\\u0641\\u064A \\u062A\\u0646\\u064A\\u0646 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627.",
    ["They're everywhere up there."] = "\\u0647\\u0646\\u064A \\u0628\\u0643\\u0644 \\u0645\\u0643\\u0627\\u0646 \\u0647\\u0648\\u0646\\u064A\\u0643.",
    ["This used to count as a work party. Minus the potluck."] = "\\u0647\\u0627\\u062F \\u0643\\u0627\\u0646 \\u064A\\u0639\\u062A\\u0628\\u0631 \\u0634\\u063A\\u0644 \\u062C\\u0645\\u0627\\u0639\\u0629\\u060C \\u0628\\u0633 \\u0645\\u0646 \\u063A\\u064A\\u0631 \\u0639\\u0632\\u064A\\u0645\\u0629.",
    ["Three or four zombies ahead."] = "\\u062A\\u0644\\u0627\\u062A\\u0629 \\u0623\\u0648 \\u0623\\u0631\\u0628\\u0639\\u0629 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627.",
    ["Tobacco farmers knew the secret: keep your hands busy."] = "\\u0627\\u0644\\u0641\\u0644\\u0627\\u062D\\u064A\\u0646 \\u0643\\u0627\\u0646\\u0648\\u0627 \\u0639\\u0627\\u0631\\u0641\\u064A\\u0646 \\u0627\\u0644\\u0633\\u0631: \\u062E\\u0644\\u064A \\u0625\\u064A\\u062F\\u064A\\u0643 \\u0645\\u0634\\u063A\\u0648\\u0644\\u0629.",
    ["Too high, bad grip. Pick another route."] = "\\u0639\\u0627\\u0644\\u064A\\u0629 \\u0648\\u0645\\u0627 \\u0641\\u064A \\u0645\\u0633\\u0643\\u0629. \\u0634\\u0648\\u0641 \\u0637\\u0631\\u064A\\u0642 \\u062A\\u0627\\u0646\\u064A\\u0629.",
    ["Two ahead. Stay where I can see you."] = "\\u062A\\u0646\\u064A\\u0646 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627. \\u062E\\u0644\\u064A\\u0643 \\u0648\\u064A\\u0646 \\u0634\\u0627\\u064A\\u0641\\u062A\\u0643.",
    ["Two bodies moving our way."] = "\\u062A\\u0646\\u064A\\u0646 \\u062C\\u0627\\u064A\\u064A\\u0646 \\u0644\\u0639\\u0646\\u0627.",
    ["Two contacts in sight."] = "\\u0641\\u064A \\u062A\\u0646\\u064A\\u0646 \\u0645\\u0628\\u064A\\u0646\\u064A\\u0646.",
    ["Two contacts. Keep them from flanking us."] = "\\u062A\\u0646\\u064A\\u0646. \\u0645\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0647\\u0645 \\u064A\\u062F\\u0648\\u0631\\u0648\\u0627 \\u062D\\u0648\\u0627\\u0644\\u064A\\u0646\\u0627.",
    ["Two contacts. Take them one at a time!"] = "\\u062A\\u0646\\u064A\\u0646. \\u0648\\u0627\\u062D\\u062F \\u0648\\u0627\\u062D\\u062F!",
    ["Two on us! Pull back!"] = "\\u062A\\u0646\\u064A\\u0646 \\u0639\\u0644\\u064A\\u0646\\u0627! \\u0644\\u0648\\u0631\\u0627!",
    ["Two zombies ahead."] = "\\u062A\\u0646\\u064A\\u0646 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627.",
    ["Two zombies. Don't let them come side by side."] = "\\u062A\\u0646\\u064A\\u0646. \\u0645\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0647\\u0645 \\u064A\\u062C\\u0648\\u0627 \\u0645\\u0639 \\u0628\\u0639\\u0636.",
    ["Waiting is just resting, but boring. Let's move."] = "\\u0627\\u0644\\u0627\\u0646\\u062A\\u0638\\u0627\\u0631 \\u0631\\u0627\\u062D\\u0629 \\u0628\\u0633 \\u0645\\u0645\\u0644\\u0629. \\u064A\\u0644\\u0627 \\u0646\\u062A\\u062D\\u0631\\u0643.",
    ["Walking the county like a census taker. Head count's way down."] = "\\u0639\\u0645 \\u0646\\u0645\\u0634\\u064A \\u0627\\u0644\\u0628\\u0644\\u062F \\u0645\\u062A\\u0644 \\u0645\\u0648\\u0638\\u0641 \\u0627\\u0644\\u0625\\u062D\\u0635\\u0627\\u0621\\u060C \\u0648\\u0627\\u0644\\u0639\\u062F\\u062F \\u0646\\u0627\\u0632\\u0644 \\u0643\\u062A\\u064A\\u0631.",
    ["Wall of walkers ahead."] = "\\u0641\\u064A \\u062D\\u064A\\u0637 \\u0645\\u0646\\u0647\\u0645 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627.",
    ["Watch it. Two zombies."] = "\\u0627\\u0646\\u062A\\u0628\\u0647\\u060C \\u062A\\u0646\\u064A\\u0646.",
    ["We have time. Let's use it carefully."] = "\\u0645\\u0639\\u0646\\u0627 \\u0648\\u0642\\u062A. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0633\\u062A\\u0641\\u064A\\u062F \\u0645\\u0646\\u0647.",
    ["We're getting wet. Let's keep an eye out for somewhere dry."] = "\\u0639\\u0645 \\u0646\\u062A\\u0628\\u0644\\u0644. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0644\\u0645\\u062D \\u0645\\u062D\\u0644 \\u0646\\u0627\\u0634\\u0641.",
    ["We've got a cluster of them ahead."] = "\\u0641\\u064A \\u062C\\u0645\\u0627\\u0639\\u0629 \\u0645\\u0646\\u0647\\u0645 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627.",
    ["We've got a single contact."] = "\\u0639\\u0646\\u0627 \\u0648\\u0627\\u062D\\u062F.",
    ["When it happens, it won't be me. Remember that. It won't be me."] = "\\u0644\\u0645\\u0627 \\u064A\\u0635\\u064A\\u0631\\u060C \\u0645\\u0627 \\u0631\\u062D \\u0643\\u0648\\u0646 \\u0623\\u0646\\u0627. \\u062A\\u0630\\u0643\\u0631 \\u0647\\u0627\\u0644\\u0634\\u064A. \\u0645\\u0627 \\u0631\\u062D \\u0643\\u0648\\u0646 \\u0623\\u0646\\u0627.",
    ["Who's going to look after all of you when I'm gone?"] = "\\u0645\\u064A\\u0646 \\u0631\\u062D \\u064A\\u0647\\u062A\\u0645 \\u0641\\u064A\\u0643\\u0646 \\u0644\\u0645\\u0627 \\u0623\\u0631\\u0648\\u062D\\u061F",
    ["Work quiet when we can. Noise draws them like hogs to a bucket."] = "\\u0627\\u0634\\u062A\\u063A\\u0644 \\u0628\\u0647\\u062F\\u0648\\u0621 \\u0644\\u0645\\u0627 \\u062A\\u0642\\u062F\\u0631. \\u0627\\u0644\\u0635\\u0648\\u062A \\u0628\\u064A\\u062C\\u064A\\u0628\\u0647\\u0645 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u062F\\u0648\\u062F \\u0639\\u0627\\u0644\\u0639\\u0633\\u0644.",
    ["Worth a try. Wasn't worth much."] = "\\u062C\\u0631\\u0651\\u0628\\u0646\\u0627\\u0647\\u0627. \\u0645\\u0627 \\u0637\\u0644\\u0639\\u062A \\u0628\\u0634\\u064A.",
    ["You holding up? You don't have to answer right away."] = "\\u0645\\u0627\\u0634\\u064A \\u0627\\u0644\\u062D\\u0627\\u0644 \\u0645\\u0639\\u0643\\u061F \\u0645\\u0627 \\u0628\\u062F\\u064A \\u062C\\u0648\\u0627\\u0628 \\u0647\\u0644\\u0623.",
    ["You were good to me. All of you. Tell them I said so."] = "\\u0643\\u0646\\u062A\\u0648\\u0627 \\u0645\\u0646\\u064A\\u062D\\u064A\\u0646 \\u0645\\u0639\\u064A\\u060C \\u0643\\u0644\\u0643\\u0646. \\u0642\\u0648\\u0644\\u0644\\u0647\\u0645 \\u0623\\u0646\\u0627 \\u0642\\u0644\\u062A \\u0647\\u064A\\u0643.",
    ["You're getting soaked. Let's find cover when we can."] = "\\u062A\\u0628\\u0644\\u0644\\u062A \\u0643\\u062A\\u064A\\u0631. \\u0623\\u0648\\u0644 \\u0645\\u0627 \\u0646\\u0642\\u062F\\u0631\\u060C \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0633\\u0642\\u0641.",
    ["Zombie! Watch out!"] = "\\u0641\\u064A \\u0648\\u0627\\u062D\\u062F! \\u0627\\u0646\\u062A\\u0628\\u0647!",
}
for en, ar in pairs(SolSpeechARLines or {}) do if S.lines[en] == nil then S.lines[en] = ar end end
S.pools = {
    ["ambient"] = { "\\u0627\\u0644\\u062C\\u0648 \\u0647\\u0627\\u062F\\u064A \\u0647\\u0644\\u0623.", "\\u0643\\u0644\\u0647 \\u0647\\u0627\\u062F\\u064A." },
    ["ambient.dusk"] = { "\\u0639\\u0645 \\u062A\\u0639\\u062A\\u0645\\u060C \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0646\\u0627.", "\\u0627\\u0644\\u0645\\u0633\\u0627 \\u062C\\u0627\\u064A." },
    ["ambient.morning"] = { "\\u0635\\u0628\\u0627\\u062D \\u0627\\u0644\\u062E\\u064A\\u0631.", "\\u0646\\u0647\\u0627\\u0631 \\u062C\\u062F\\u064A\\u062F\\u060C \\u064A\\u0644\\u0627." },
    ["ambient.rain"] = { "\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u0639\\u0645 \\u062A\\u0634\\u062A\\u064A.", "\\u0627\\u0644\\u0634\\u062A\\u0627 \\u0646\\u0627\\u0632\\u0644\\u0629\\u060C \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0644\\u0627\\u0642\\u064A \\u0633\\u0642\\u0641." },
    ["anchor"] = { "\\u062E\\u0644\\u064A\\u0643 \\u0647\\u0648\\u0646." },
    ["background"] = { "\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u062D\\u0643\\u064A\\u0644\\u0643." },
    ["banter"] = { "\\u0623\\u0646\\u0627 \\u0645\\u0639\\u0643.", "\\u0643\\u0644\\u0647 \\u062A\\u0645\\u0627\\u0645\\u061F", "\\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0643\\u0645\\u0644." },
    ["banter.distraction"] = { "\\u0647\\u064A\\u0647! \\u0645\\u0646 \\u0647\\u0648\\u0646!", "\\u0644\\u0647\\u0648\\u0646! \\u0644\\u0647\\u0648\\u0646!" },
    ["banter.follow"] = { "\\u0623\\u0646\\u0627 \\u0648\\u0631\\u0627\\u0643.", "\\u0643\\u0645\\u0644\\u060C \\u0623\\u0646\\u0627 \\u062D\\u0627\\u0645\\u064A\\u0629 \\u0636\\u0647\\u0631\\u0643.", "\\u0648\\u064A\\u0646 \\u0645\\u0627 \\u0628\\u062F\\u0643\\u060C \\u0623\\u0646\\u0627 \\u0645\\u0639\\u0643.", "\\u0639\\u064A\\u0646\\u064A \\u0639\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642." },
    ["banter.idle"] = { "\\u0644\\u0633\\u0627 \\u0645\\u0637\\u0648\\u0644\\u064A\\u0646\\u061F", "\\u0634\\u0648 \\u062E\\u0637\\u062A\\u0646\\u0627\\u061F", "\\u0648\\u0642\\u0641\\u0646\\u0627 \\u0643\\u062A\\u064A\\u0631 \\u0647\\u0648\\u0646." },
